import {INFO,sampleGrid,hsv} from './engine.mjs';
export class Scanner{
 constructor({canvas,video,onReading,onCapture,onError}){Object.assign(this,{canvas,video,onReading,onCapture,onError});this.ctx=canvas.getContext('2d',{willReadFrequently:true});this.active=false;this.generation=0;this.mode='camera';this.face='F';this.auto=true;this.scale=1;this.dx=0;this.dy=0;this.rotation=0;this.stableAt=0;this.lastKey='';this.lastTime=-1;this.lastTick=0;this.frozenUntil=0;this.canvas.width=600;this.canvas.height=600;this.drag=null;canvas.addEventListener('pointerdown',e=>{if(this.mode!=='photo')return;this.drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!this.drag)return;this.dx+=(e.clientX-this.drag.x)*600/canvas.clientWidth;this.dy+=(e.clientY-this.drag.y)*600/canvas.clientHeight;this.drag={x:e.clientX,y:e.clientY};this.drawPhoto();});for(let ev of ['pointerup','pointercancel'])canvas.addEventListener(ev,()=>this.drag=null);}
 async start(){const gen=++this.generation;this.active=true;this.mode='camera';try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access needs a secure browser. Open this app in Safari or Chrome, or use a photo.');const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});if(!this.active||gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return;}this.stream=stream;this.video.srcObject=stream;await this.video.play();if(!this.active||gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return;}stream.getVideoTracks()[0].addEventListener('ended',()=>{if(this.active){this.stop();this.onError('The camera stopped. Start it again, or use a photo.');}});this.frame();}catch(e){if(gen!==this.generation)return;this.stop();const messages={NotAllowedError:'Camera permission was blocked. Allow the camera in your browser settings, or add a photo instead.',NotFoundError:'No camera was found. You can upload a photo or enter the colors by hand.',NotReadableError:'The camera is busy. Close other apps using it and try again.'};this.onError(messages[e.name]||e.message);}}
 stop(){this.active=false;this.generation++;if(this.stream)this.stream.getTracks().forEach(t=>t.stop());this.stream=null;this.video.srcObject=null;if(this.raf)cancelAnimationFrame(this.raf);if(this.vfc&&this.video.cancelVideoFrameCallback)this.video.cancelVideoFrameCallback(this.vfc);this.stableAt=0;}
 setFace(face){this.face=face;this.lastKey='';this.stableAt=0;this.frozenUntil=performance.now()+1700;}
 frame(){if(!this.active||this.mode!=='camera')return;const t=performance.now();if(this.video.readyState>=2&&this.video.videoWidth&&this.video.currentTime!==this.lastTime&&t-this.lastTick>85){this.lastTime=this.video.currentTime;this.lastTick=t;this.drawSource(this.video);this.analyze(t);}if(this.video.requestVideoFrameCallback)this.vfc=this.video.requestVideoFrameCallback(()=>this.frame());else this.raf=requestAnimationFrame(()=>this.frame());}
 drawSource(source){const w=source.videoWidth||source.naturalWidth,h=source.videoHeight||source.naturalHeight;const s=600/Math.min(w,h)*(this.mode==='photo'?this.scale:1);this.ctx.fillStyle='#162721';this.ctx.fillRect(0,0,600,600);this.ctx.save();this.ctx.translate(300+this.dx,300+this.dy);this.ctx.rotate(this.rotation*Math.PI/2);this.ctx.drawImage(source,-w*s/2,-h*s/2,w*s,h*s);this.ctx.restore();}
 analyze(t=performance.now()){const reading=sampleGrid(this.ctx,90,90,420);this.reading=reading;const key=reading.colors.join('');const centerOK=reading.colors[4]===this.face;const uniform=reading.uniform.every(Boolean);const bright=reading.rgbs.every(rgb=>hsv(rgb)[2]>.19);const clear=reading.confidence.every(c=>c>.3);const diff=this.previous?reading.rgbs.reduce((sum,rgb,i)=>sum+rgb.reduce((a,b,j)=>a+Math.abs(b-this.previous[i][j]),0),0)/27:100;this.previous=reading.rgbs;const ok=centerOK&&uniform&&bright&&clear&&diff<14&&t>this.frozenUntil;if(!ok||key!==this.lastKey)this.stableAt=0;if(ok&&!this.stableAt)this.stableAt=t;this.lastKey=key;let progress=this.stableAt?Math.min(1,(t-this.stableAt)/1700):0;this.onReading({...reading,progress,centerOK,message:t<this.frozenUntil?'Turn the whole cube to the next face':!centerOK?`Show the ${INFO[this.face].color.toLowerCase()} center` :!bright?'Try brighter, even lighting':!uniform||!clear?'Align all nine stickers with the dots':progress>0?'Hold still…':'Fit the face inside the guide'});if(this.mode==='camera'&&this.auto&&progress>=1)this.capture();}
 capture(){if(!this.reading)return;this.stableAt=0;this.frozenUntil=performance.now()+2000;this.onCapture({colors:[...this.reading.colors],rgbs:this.reading.rgbs.map(a=>[...a]),confidence:[...this.reading.confidence],thumbnail:this.canvas.toDataURL('image/jpeg',.6)});}
 async photo(file){this.stop();this.mode='photo';if(!file.type.startsWith('image/'))throw new Error('Choose a JPEG, PNG, WebP, or another browser-readable image.');if(file.size>25*1024*1024)throw new Error('Choose an image smaller than 25 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();this.image=img;this.scale=1;this.dx=0;this.dy=0;this.rotation=0;this.drawPhoto();}catch(e){throw new Error('This image could not be read. Try a JPEG or PNG photo.');}finally{URL.revokeObjectURL(url);}}
 drawPhoto(){if(this.image){this.drawSource(this.image);this.analyze();}}
}
